/* Spielleitung: Zuflüchte (Sanctum, S. 2–18) – Haven-Erschaffung, Haven-Spielleitung, Wyrmpit – übersetzt.
   Seitenangaben = Buchseiten von „Sanctum“ (Bookviewer-Buch ht_z4). */
window.HT_NACH = window.HT_NACH || {};
(function(){
var BK = "ht_z4", BL = "Sanctum";
function sec(id, t, p, b){ return {id:id, t:t, p:p, bk:BK, bl:BL, b:b}; }
function p(x, k){ return {t:"p", x:x, k:k ? 1 : 0}; }
function h(x, pg){ var o = {t:"h", x:x}; if(pg){ o.p = pg; o.bk = BK; o.bl = BL; } return o; }
function ul(a){ return {t:"ul", x:a}; }
function ks(l, a){ return {t:"kasten", h:l, b:a}; }
function C(a, n){ var o = {t:"karten", x:a.map(function(c){ return {t:c[0], b:c.slice(1).map(function(x){ return typeof x === "string" ? x : x; })}; })}; if(n) o.n = n; return o; }
function G(n, cols){ return {t:"grid", n:n, x:cols}; }
function note(name, paras){ return ks(name, paras.map(function(x){ return p(x, true); })); }
var A = "Anhaltend", S = "Sofort";
function F(n, res, x, art, extra){ return [n, x].concat(extra || []).concat([{t:"p", k:1, x:"[" + res + " · " + art + "]"}]); }

var haven = {id:"zuflucht", t:"Zuflüchte", p:2, secs:[
 sec("einleitung", "Einleitung", 2, [
  G(2, [[
   p("Ein verlassener U-Bahnhof, wieder aufgebaut und mit windschiefen Verteidigungsanlagen verstärkt, um die wilden Kreaturen des Herzens fernzuhalten. Eine Ansammlung zusammengezurrter Skiffs und Lastkähne, die über die ölige Oberfläche eines unterirdischen Sees treibt. Ein verdrehter Leuchtturm am Rand einer Klippe, umgeben von bleichen, krächzenden Vögeln und bemannt von zwei verzweifelten Familien."),
   p("Das Grundspiel von *Heart* setzt voraus, dass die Delver genau das tun: delven. *Heart* ist vor allem ein Spiel darüber, in der Stadt unter der Stadt auf der Suche nach Antworten ins Unbekannte vorzudringen – aber das muss nicht sein."),
   p("In *Sanctum* richten wir den Fokus auf einen anderen Spielstil: eine Kampagne rund um eine einzelne zentrale Landmarke, die die Spieler mit Hilfe der Spielleitung erschaffen. Wir führen euch durch den Bau eines Havens und die Gestaltung der Welt um ihn herum. Dann – und das ist der aufregendste Teil – könnt ihr ihn in Stücke schlagen (oder es versuchen), und zwar mit einer von vier Arten von Engeln, den albtraumhaften und unwirklichen Agenten des Heart Itself."),
   ks("Havens", ["Wenn wir „Haven“ sagen, meinen wir „Landmarke mit der Domain **Haven**“, also einen stabilen Ort im Herzen, an dem sich Leute um der Gemeinschaft willen zusammengetan haben und nicht für einen einzelnen Zweck.", "Es gibt viele Orte, an denen Leute leben, die nicht als Havens gelten: Forschungsstationen, Wachposten, Kultverstecke, verräterische Tempel, Einsiedeleien und so weiter."])
  ], [
   h("Das unglückliche Schicksal des Gris Hannemann"),
   p("Gris Hannemann, ein menschlicher Schriftsteller, war berühmt für seine Arbeiten in Groschenheften. Er gab vor, ein Entdecker von Rang zu sein, und beschrieb seine Taten in reißerischen Berichten wie *The Lustful She-Gnolls of Nujab*, *The Silver Song of the Ice Nymphs*, *Death Drives A Vermissian Carriage* und *The Bloodthirsty Automata of Magwan Porth*. Als der Absatz seiner Novellen versiegte und seine Gläubiger anklopften, floh er in die Stadt unter der Stadt, auf der Suche nach a) Inspiration und b) einem Versteck vor den Verbrechersyndikaten, die seine Schulden eingefordert hatten."),
   p("Im Herzen hörte er von Engeln, und etwas an ihnen beflügelte seine Fantasie; er wanderte tagelang, oft allein, um einen zu erblicken. Ein halbes Jahrzehnt nach seiner ersten Expedition kehrte er als veränderter Mann nach Spire zurück, mit Bergen von Notizen über diese unheimlichen Wesen."),
   p("Er verkündete, eine Taxonomie der Engel erstellt zu haben, ihr stotterndes unwirkliches Blut getrunken und von etwas, das er The Convocation nannte, Einblick in die Welten jenseits von Licht und Schatten erhalten zu haben. Er schloss einen Handel mit seinem alten Verleger, der darauf bestand, die Notizen etwas aufzupeppen, und veröffentlichte das weitgehend unbeachtete und von der Kritik ignorierte *Beyond the Edge of Madness: A Year in the City Beneath*. Das Buch verkaufte sich nicht, und seine Gläubiger spürten ihn auf; seine Leiche wurde am Morgen nach seiner kaum besuchten Release-Party im Silver Quarter im Kanal treibend gefunden."),
   p("Schon der Anblick eines Engels kann einen Menschen in den Wahnsinn treiben. Bei der instabilen Realität des Herzens ist unklar, ob Hannemann tatsächlich mehrere völlig neue Arten von Engeln entdeckt hat oder nur mehrere dreitägige Sauftouren mit allem hatte, was er in der Wildnis an Drogen zusammenkratzen konnte. Für die Bewohner des Herzens, die ihn überlebten, ist das unglücklicherweise egal."),
   p("Das Herz erschafft tatsächlich Monster nach seinen Vorgaben: bessere, Kreaturen für einen einzigen Zweck, Maschinen aus Knochen und Zwischengewebsflüssigkeit. Niemand kann sich erinnern, sie zuvor gesehen zu haben, aber genaue Erinnerungen sind in der Stadt unter der Stadt eine knappe Ressource – vielleicht war er nur der Erste, der alles aufgeschrieben hat."),
   p("Hannemanns Notizen zu Havens und den bekannteren Arten von Engeln sind über dieses Buch verteilt.")
  ]])
 ]),
 sec("domains", "Haven-Erschaffung: Domains", 3, [
  p("Wollt ihr, dass sich eure Spieler mit einem Haven verbunden fühlen, ist es am besten, wenn sie ihn selbst erschaffen. Setzt euch zu Beginn der Kampagne an einen Tisch (oder einen virtuellen Tisch, wenn ihr online spielt) und führt sie durch den Erschaffungsprozess. Wir haben ihn auf eine Reihe von Fragen heruntergebrochen, um ihn so einfach wie möglich zu machen, aber lasst euch davon nicht einschränken. Ihr könnt so tief ins Detail gehen, wie ihr wollt; lasst nur einige Geheimnisse zum Erkunden im Spiel übrig."),
  p("Denkt daran, dass das, was ihr euch ausdenkt, nicht in Stein gemeißelt ist. Ihr könnt es ändern, wenn sich die Idee entwickelt; vielleicht merkt ihr zum Beispiel, dass der Haven die Domain **Warren** braucht oder auf **Tiefe 3** statt **Tiefe 2** liegt. Tauscht gern Dinge aus, damit er zu eurer Vision passt."),
  h("Domains"),
  p("Das Erste, was beim Bau eines Havens zu bedenken ist, sind die Domains, die ihr ihm gebt. Er hat zwangsläufig die Domain Haven (sonst wäre er kein Haven), aber überlegt, welche anderen Domains ihn beeinflussen, und wählt eine oder zwei, um ihm etwas Geschmack zu geben. Unten stehen Beispiele, wie jede Domain einen Haven beeinflussen kann."),
  C([
   ["Cursed", "Im Kellergewölbe der Kneipe wächst ein riesiges, hungriges Maul aus der Wand, und Kinder der Gegend schleichen sich hinein und fordern sich gegenseitig heraus, die Hand hineinzustecken; die Hounds hier haben einen Graben mit etwas angelegt, das wie Magensäure aussieht (und riecht), mit Flimmerhärchen, die unter der Oberfläche wogen; es gibt eine große Heartsblood-Enklave in der Siedlung, und durchreisende Cleaver kommen oft vorbei, um ihre Ehrerbietung zu erweisen."],
   ["Desolate", "Eine vergessene Zivilisation nutzte diese Plattform, um etwas Lebenswichtiges aus der Erde zu fördern, und jetzt umgeben pfadlose, verwüstete Ödländer sie; die Siedlung klebt an den Wänden einer Schlucht, und die Leute suchen Schutz in Höhlen und versuchen, das Grollen in der Dunkelheit unter ihnen zu ignorieren; dieser Ort war einmal ein Tempel, aber Generationen souvenirhungriger Pilger haben alle Ikonografie von den Wänden gekratzt."],
   ["Occult", "Der Haven ist eine Art Schule – Studenten kommen her, wenn sie echte Magie lernen wollen, und einige überleben den Prozess sogar; im Zentrum der Siedlung steht ein sich verschiebender Sockel aus Messing und Eisen von enormer Komplexität, der meditative Okkultisten anzieht; der Haven ist ein fortlaufendes, jahrhundertelanges magisches Ritual, und wenige Bewohner sind sich seines Zwecks sicher."],
   ["Religion", "Diese Splittergruppe (The Dominion of the Sunken Sun), aus dem Temple of the Moon Beneath verbannt, bietet Reisenden Zuflucht samt Bergen von Werbematerial; es heißt, ein blutverkrusteter, glorreicher Engel von Charnel bade hier im Wasser und heile die Kranken; ein wahnsinnig machender Ort, an dem mehrmals am Tag (und ohne erkennbare Vorwarnung) laute Glocken geläutet werden, um die Majestät eines Gottes zu feiern, den man nur durch Musik benennen kann."],
   ["Technology", "Der Haven wandelt unsicher auf vielen knarrenden Beinen dorthin, wohin der Rat der Engineers (ein Gnoll, zwei Menschen und ein Geist) ihn haben will; das Vermissian Collective hat hier eine Denkmaschine aus sorgfältig geernteten Bewusstseinen gebaut und füttert sie mit Fragen wie ein Orakel; die Ventile und Schalter im Zentrum des Havens erlauben die Kontrolle über Umwelt und Form der Siedlung, aber drei rivalisierende Sekten mit verschiedenen Ausgaben des Handbuchs ringen um die Kontrolle."],
   ["Warren", "Die Tradition verlangt, dass die Kirche alle zwanzig Jahre abgerissen und auf ihren Ruinen eine neue gebaut wird, und nun reichen die Untergeschosse über hundert Fuß unter die Erde; sich in voller Größe aufzurichten bringt hier Unglück, also bauen die gebückten Bewohner ihre Decken niedrig, um Glück zu haben; dieser Ort ist ein Bergwerk, in dem Gräbertrupps Gestein abklopfen, um geflügelte, humanoide Fossilien zu gewinnen."],
   ["Wild", "Die Häuser stehen auf Stelzen, um sie aus stinkendem Wasser herauszuhalten, das von leuchtenden Insekten sprudelt; jeder hat mindestens ein Heartsblood-Haustier und weniger als die empfohlene Zahl Finger; riesige, flugunfähige Megacorviden krächzen und stürzen auf der Suche nach Futter oder einem Schlafplatz umher, und die Bewohner betrachten sie als heilige Geschöpfe."]
  ], "4s"),
  note("Hallow", [
   "Lauter verschlossene Türen und geschlossene Fensterläden, Gackern aus schattigen Gassen und Augen – immer wachsam, immer urteilend. Die seuchenzerfressenen Hexen, die diesen Ort führen, scheinen zu glauben, sie hätten ein Monopol auf die Convocation, und weigern sich, meine Fragen zu beantworten.",
   "Tatsächlich weigern sie sich, überhaupt offen mit den Nichtinfizierten zu sprechen, und haben mit Getue und Bluff einen Kult aus Furcht und Verehrung um sich herum zusammengebastelt. Die Blutkrankheit, die sie teilen, verleiht ihnen ein gewisses Maß an prophetischer Kraft, und es scheint keinen Mangel an leichtgläubigen Kultisten zu geben, die ihr Los mit den Witches of Hallow verbinden wollen.",
   "Nach einer katastrophalen Konfrontation reiste ich bald nach meiner Ankunft ab. Ich glaube, dass sie mich, so abweisend sie waren, nun aufspüren; zweifellos interessieren sie sich dafür, mehr über meine Methoden und meine Forschung zu erfahren. Ich habe verstanden, dass sie den Dreh heraushaben, sich mit den Raubtiergebäuden anzufreunden, die hier existieren. Ich bin mir sicher, dass der vernagelte Schneiderladen, den ich an vier anderen Orten wiederholt gesehen habe, Teil ihrer Pläne ist. Ich bin kein Narr: Ich werde nicht versuchen, Zugang zu bekommen. Aber ich werde den Laden niederbrennen, wenn sie es wagen, sich in mein Vorhaben einzumischen."
  ])
 ]),
 sec("tiefe", "Tiefe", 5, [
  p("Tiefen sind ein grober Anhaltspunkt dafür, wie nah dein Haven am Heart Itself liegt (und damit wie seltsam er ist). Je tiefer du kommst, desto kreativer kannst du werden – aber desto härter musst du arbeiten, um ein Gefühl von Menschlichkeit zu bewahren. Bestehen deine Bewohner zum Beispiel alle aus Liedern, die in Gläsern gefangen sind, wird es schwer, die Spieler dazu zu bringen, sich persönlich mit ihnen zu verbinden."),
  C([
   ["Tiefe 1", "Diese Havens am Rand von Derelictus folgen noch den meisten Regeln von Raum und Zeit. Es gibt keine seltsamen Portale in andere Welten, die Wände bestehen hauptsächlich aus Wand statt aus Fleisch oder intelligentem Kristall, und die Leute sehen im Grunde aus wie Leute. Im Allgemeinen verlassen sich diese Orte nicht auf Magie oder seltsame Technik, um intakt zu bleiben, und sehen daher aus wie echte unterirdische Bauten.", "Landmarken der Tiefe 1 sind sicherer als tiefere Orte, aber sie geraten meist unter die Kontrolle einer oder mehrerer bestehender Machtstrukturen (z. B. des Vermissian Collective, der Hounds oder der Church of the Moon Beneath). Das kann die Bewohner verärgern, wenn sie lieber ihren eigenen Weg gehen würden."],
   ["Tiefe 2", "Diese Landmarken haben etwas definitiv Seltsames an sich. Vielleicht funktioniert die Schwerkraft nicht richtig, die Straßen ordnen sich neu an, wenn niemand hinsieht, oder Geister gehen neben den Lebenden. Die Bewohner sind ebenso seltsam, da sie sich absichtlich oder unabsichtlich von der normalen Gesellschaft abgetrennt haben.", "Tiefe 2 ist deutlich gefährlicher als Tiefe 1, daher sind die meisten Havens auf dieser Stufe sorgfältig bewacht. Mauern, Tore und Verteidigungsanlagen sind üblich, und Hounds übernehmen eine aktive Rolle beim Schutz der Bevölkerung, statt wie auf Tiefe 1 zu versuchen, die Gesellschaft im Gleichgewicht zu halten. Die Leute hier sind Fremden gegenüber entsprechend misstrauisch, aber wenn du deine Vertrauenswürdigkeit beweisen (oder vortäuschen) kannst, verkaufen dir die meisten gern eine warme Mahlzeit und tauschen Geschichten."],
   ["Tiefe 3", "Werde so seltsam, wie du willst. Du musst dir keine Gedanken mehr darüber machen, ob es Sinn ergibt. Meere, Wälder, fremde Himmel, riesige pulsierende Organe, Eishöhlen, verfluchte Grabkammern jenseitiger Zauberer-Könige, Geister ganzer Siedlungen, die andere Siedlungen heimsuchen; wenn es zum Gesamtthema von Heart passt, nur zu.", "Havens in dieser Tiefe sind viel seltener. Es ist schwer, irgendeine Art von Stabilität zu halten, und doppelt so schwer, wenn man eine Gemeinschaft versorgen will. Jede dauerhafte Landmarke, die du findest, hat einen Trick, sich selbst intakt zu halten, sei es eine einzigartige Lebensweise, Handel mit jenseitigen Wesen, fortgeschrittene (wenn auch nicht ganz verstandene) Technik oder die Anpassung ihrer Körper an die Umgebung."],
   ["Tiefe 4", "Das Heart Itself. Hier gibt es keine Havens … oder vielleicht ist es ein einziger großer Haven! Das liegt bei dir. (Letzteres ist allerdings unwahrscheinlich.)"],
   ["Rogue", "Willst du einen mobilen Haven, der zwischen Tiefen wechseln kann, erlaubt dir der Tag Rogue, ihn zu platzieren, wo du willst, wann immer es erzählerisch passt. Achte aber darauf, dass das Bewegen schwierig ist. Gib ihm ungewöhnliche Voraussetzungen für den Start, lass ihn Schutz brauchen, wenn er zwischen den Tiefen wechselt, oder lass Älteste das Sagen haben, die erst überzeugt werden müssen, ihn überhaupt zu bewegen."],
   ["Fracture", "Fractures sind außerdimensionale Schlupfwinkel, die parallel zur Standardebene der Realität existieren. Man kann sie von mehreren Orten aus betreten, per Ritual oder über mehrere speziell vorbereitete Portale. Fractures lassen dich beim Aufbau des Havens kreativ werden, sind aber nur mit Mühe zu erreichen. Außerdem fehlt ihnen aufgrund ihrer von Natur aus seltsamen Art oft etwas Konkretes, womit sich Spielerfiguren verbinden können, also sei beim Bau vorsichtig."]
  ], 3)
 ]),
 sec("besonderes", "Etwas Einzigartiges", 6, [
  G(2, [[
   p("Etwas macht deinen Haven ungewöhnlich: eine Regel, die er bricht (ob wissenschaftlich oder gesellschaftlich), ein Gott, den sie verehren, eine besondere Ressource, ein anderes prägendes Merkmal. Du wirst feststellen, dass in den Havens des Grundbuchs jeder eine (oder mehrere) Wendungen oder Veränderungen hat, die ihn von den anderen abheben – etwas Großes, meist von außen Sichtbares, statt nur andere Leute darin zu haben."),
   p("**Sei mutig.** Heart lässt dir viel Raum zum Experimentieren und für etwas Interessantes; selbst der Ort, an dem du dein Haupt zur Ruhe bettest und Malak kippst, sollte etwas Bemerkenswertes haben."),
   p("Außerdem: Hab keine Angst, die Welt um den Haven herum zu verändern. Das Herz, durch das deine Spieler streifen, gehört dir allein und kann (und sollte) sich von dem im Grundbuch unterscheiden. Zum Beispiel deuten wir an, dass es in der Stadt unter der Stadt mehrere Bauten gibt, die den Deep Apiarists gewidmet sind, aber vielleicht dürfen sie in deinem Spiel nur in deinem Haven wirken. Wir haben standardmäßig keine Megafauna oder wandernden Dörfer, aber vielleicht ist dein Haven auf dem Rücken eines riesigen Käfers gebaut, der nach seinem eigenen unergründlichen Fahrplan zwischen den Tiefen umherspaziert."),
   note("Grip Station", [
    "Die Weisen des Vermissian sind ein seltsamer Haufen; sie sind besessen von dem, was sein könnte, statt von dem, was ist. Sie widmen ihr Dasein der zielstrebigen Verfolgung des Möglichen und wandern durch dieses unwirkliche Netz auf der Suche nach – nun, nicht nach Antworten, aber gewiss nach Fragen.",
    "Es ist anstrengend, längere Zeit in ihrer Nähe zu sein. Eine Weile hielten sie mich für einen Einfaltspinsel und ignorierten mich gern (und verlangten zu viel für unbequeme, aber im Großen und Ganzen ruhige Unterkünfte). Dann sah einer von ihnen meine Notizen und begann offenbar, mich als intellektuell ebenbürtig zu betrachten.",
    "Er sprach lange über die verschiedenen „Facetten“ des Vermissian: all seine möglichen Zukünfte und alternativen Vergangenheiten, die über dimensionale Drehscheiben zugänglich sind. Er sprach von einer Realität, zerbrechlich wie Spinnglas, in der der Incident nicht geschah und die Züge tatsächlich fahren; einem Land der Toten, in dem Gespenster von körperlosen Maschinen in ihr Jenseits gefahren werden; wilden, gesetzlosen Ödländern, in denen wahnsinnige Maschinenkultisten Reiche errichten und rivalisierende Sekten als Ersatzteile ernten.",
    "Aber warum das Unwirkliche und kaum Existierende suchen, wenn das, was schon hier ist, purpurn und herrlich, so faszinierend ist?"
   ])
  ], [
   h("Beispiele"),
   ul(["*Der Haven ist aus Fleisch und Blut einer einzelnen Kreatur (die möglicherweise einmal ein Mensch war) in einem Keller gewachsen. Die Kreatur ist nett genug zum Reden, hat aber eine eigene Agenda, getrennt von den Leuten, die den Ort führen.*","*Der Haven existiert nur in unserer Welt, während ein Aelfir-Lied aufgeführt wird. Nicht jeder weiß das, und manchmal erscheint er zufällig, verschmilzt mit Cabaret-Bars in Derelictus oder ruckelt bei einem betrunkenen Lagerfeuer-Singsang ins Bild.*","*Der Haven ist zugleich Bibliothek und Friedhof: Menschen werden hier begraben und werden langsam zu Büchern, die ihr Leben schildern.*","*Der Haven ist besessen davon, eine originale Vermissian-Kutsche wieder aufzubauen und in Gang zu bringen.*","*Der Haven betet den riesigen Krötengott Plür an und füttert die Statue auf dem Marktplatz mit Gegenständen magischer Resonanz im Austausch für göttlichen Schutz.*","*Zweimal im Jahr füttert der Haven einen „glücklichen“ Bewohner an das kolossale Aasschwein, das unter dem Marktplatz vergraben liegt. Im Gegenzug lässt das Schwein sie seinen Bauch aufschlitzen und armvollweise unheimliche Gedärme herausziehen, mit denen sie die Zukunft vorhersagen (solange sie sie zurücklegen und die Wunde danach vernähen).*","*Jahrhunderte aufeinandergebauter Reliquienkatakomben sind eingestürzt und haben den Haven voller durcheinandergeworfener Heiligenknochen hinterlassen; gelegentlich erwachen sie zu einem hässlichen Gestalt-Wesen.*","*Der Haven ist um eine ewig brennende Kerze in einem Salzkreis herum gebaut: den ersten Schutz, der gegen das Herz errichtet wurde. Wird der Salzkreis je durchbrochen, fällt der Haven.*","*Der Haven wird von Kannibalen geführt, die Nicht-Kannibalen als Bürger zweiter Klasse behandeln und gelegentlich ein neues Mitglied mit einem üppigen Festmahl in ihre Gemeinde aufnehmen, bei dem ein unbeliebtes Gemeinschaftsmitglied serviert wird.*"])
  ]])
 ]),
 sec("gesichter", "Gesichter", 7, [
  p("Ein Haven kann zwischen einer Handvoll und Hunderten von Bewohnern haben, viele davon nur zeitweilig, wie etwa im Temple of the Moon Beneath und den umliegenden Gebieten auf Tiefe 1. Du musst aber nicht alle ausarbeiten, ganz im Gegenteil. Denke in Gruppen und gib jeder ein Gesicht."),
  p("Ein Gesicht ist ein Vertreter einer Bewegung, Fraktion oder Idee im Haven. Wenn die Spielerfiguren mit ihm interagieren, interagieren sie mit der Gruppe, zu der es gehört, als Ganzes. Du musst dich nicht auf ein Gesicht pro Organisation beschränken, aber angesichts des Umfangs von Heart-Kampagnen (und weil die Regeln gefährliche Expeditionen ins Unbekannte abbilden und nicht Kleinstadtpolitik) sollte eines reichen."),
  p("Gib den Spielern die Möglichkeit, mit diesen Gruppen verbunden zu sein. Nicht jeder muss der beste Kumpel der abgebrühten Tante sein, die die Siedlung leitet, aber wenn ein oder zwei Spieler sie kennen (oder von ihr aufgezogen wurden, nachdem ihre Eltern starben), hilft das, die Geschichte zusammenzuhalten."),
  C([
   ["Wer stützt den Status quo?", "Jeder Haven (auch wenn sie es nicht zugeben wollen) hat einen Verwalter. Er ist für alle wichtigen Entscheidungen verantwortlich und bekommt die Schuld, wenn etwas schiefgeht, egal ob er sich seine Position durch jahrelanges Vertrauen und harte Arbeit, hinterhältige Geschäfte oder dummes Glück verdient hat. Diese Leute sind meist völlig überfordert und kämpfen darum, alles am Laufen zu halten, daher wollen sie oft, dass alles bleibt, wie es ist – auch wenn das gefährlich oder ineffizient ist.", {t:"p", k:1, x:"Warum ist es dieser Person wichtig, den Status quo zu wahren? Wer hilft ihr, die Kontrolle zu behalten? Was verliert sie, wenn sich Dinge ändern?"}],
   ["Wer will etwas aufrütteln?", "Jede Gemeinschaft hat einen Rebellen. Dieses Gesicht hält es für wichtig, den Haven zum Besseren zu verändern, wird aber von denen, die bereits die Kontrolle haben, daran gehindert. Er hat viel Arbeit für Delver, aber wegen fehlender Mittel versucht er oft, die Spielerfiguren aus philosophischen statt finanziellen Gründen zu überzeugen – oder indem er ihnen einen Anteil am Haven anbietet, sobald er an der Macht ist.", {t:"p", k:1, x:"Was will diese Person ändern? Wer steht hinter ihr? Welche Hindernisse liegen in ihrem Weg, und wie könnten die Spielerfiguren helfen?"}],
   ["Wer vertritt die Menschen insgesamt?", "Es gibt wahrscheinlich ein Handwerk, einen Glauben oder ein gemeinsames Ziel, das die Bevölkerung eint. Dieses Gesicht – die Stimme – vertritt diese Idee. Obwohl der Rebell und der Herrscher Autorität haben, lässt sich echte Macht nur halten, wenn das Volk der Stimme mit dem, was geschieht, einverstanden ist. Wenn die Spielerfiguren mit der Stimme interagieren, interagieren sie mit der Siedlung als Ganzes. Die Stimme verändert sich, um darzustellen, was mit der Bevölkerung geschieht. Hat die Gemeinschaft einen Angriff erlitten, ist die Stimme verwundet; hungert die Gemeinschaft, ist sie hager und unterernährt; feiert das Volk, ist sie betrunken und singt.", {t:"p", k:1, x:"Was tun die einfachen Leute im Haven? Was brauchen sie von den Spielerfiguren – und was können sie im Gegenzug bieten?"}]
  ]),
  ks("Nicht-Nichtspielerfiguren", ["Die in diesem Abschnitt beschriebenen Rollen müssen nicht von Nichtspielerfiguren ausgefüllt werden; es gibt reichlich Gelegenheit für Spielerfiguren, sie stattdessen zu übernehmen. Wahrscheinlich steigt die Art motivierter Persönlichkeit, die zum Delver wird, in einer Gemeinschaft zu Ansehen auf. Es ergibt auch eine gute Geschichte, wenn die Spielerfiguren direkt und nicht nur am Rande für das Gedeihen oder den Untergang des Havens verantwortlich sind."])
 ]),
 sec("kunst", "Kunst", 8, [
  p("Kunst ist in der Stadt unter der Stadt überall. Die Bewohner schaffen sie zwanghaft, während sie versuchen, die fremde Welt um sich herum zu verstehen, und dein Haven wird da keine Ausnahme sein. Welche Art von Kunst, Handwerk oder Unterhaltung bringen sie hervor, und wie spiegelt sie den Zustand des Havens wider?"),
  h("Beispiele"),
  G(2, [[
   ul(["*Schwarzhumorige Theaterstücke über legendäre Schurken und Bestien der Stadt unter der Stadt.*","*Gemeinschaftslieder mit einem wiederkehrenden Refrain, zu dem jeder Strophen hinzufügt; bringt dir jemand seine Strophe bei, gilt es als Ehre, sie zu singen.*","*Grell bemalte Architektur in schrillen, aufeinanderprallenden Mustern, die den Betrachter verstören sollen.*","*Axttanzen, das wie Schwerttanzen ist, aber wegen des wilden Schwingens etwas gefährlicher.*","*Halb improvisierte Stücke, in denen eine Reihe von Stock-Figuren die Herausforderungen des Herzens bewältigen; die meisten sterben vor Ende der Aufführung.*","*Erbittert verteidigte Graffiti-Plätze, an denen Bewohner ihre Leistungen und ihr Können (als Kämpfer, Okkultisten, Priester, Liebhaber usw.) in immer größeren und komplexeren Schriften auflisten.*"])
  ], [
   ul(["*Eine wilde Bestie fangen, sie mit Luftschlangen schmücken und laufen lassen, während mehrere Champions versuchen, sie nur mit Stoßdolchen zu Fall zu bringen.*","*Aufwendige Porträts von Damnou, der Drow-Mondgöttin, als Triptychon; dein Porträt gilt als Ausdruck deines Glaubens, und die Leute geben vergleichsweise riesige Summen für Pigmente und Verzierungen aus.*","*Sturzbetrunken versuchen, Gedichte aufzusagen; je länger das Gedicht und je betrunkener der Vortragende, desto beeindruckender die Leistung.*","*Innereienpasteten, gewürzt mit furchterregenden Likören.*","*Flickenmäntel weben für Leute, die die Siedlung verlassen, um Hounds zu werden; der Haven hat eine starke Tradition, junge Leute zum Regiment zu schicken, und unterhält eine Gedenkwand für die im Dienst Gefallenen.*","*Systeme aus Slang und Rotwelsch schaffen, die mit komplexen Regeln und Rhythmen Außenstehende verwirren.*"])
  ]])
 ]),
 sec("rolle", "Rolle", 8, [
  p("Spielerfiguren sind ungewöhnliche Leute, die in der Stadt unter der Stadt wohl kein ruhiges Leben führen. Ermutigt die Spieler, darüber nachzudenken und zu diskutieren, warum sie im Haven willkommen sind (vielleicht widerwillig) und warum Leute beschlossen haben, mit ihnen eine Gemeinschaft aufzubauen. Unten stehen einige Ideen für Rollen in Siedlungen, nach Charakterklassen aufgeteilt, aber lasst euch davon nicht einschränken."),
  C([
   ["Cleaver", "Jagen nach Essen oder Rohstoffen, die zu Vorräten verarbeitet werden; Rat in Angelegenheiten des Heart Itself; eine Grenzstadt vor wilden Tieren und Plünderern schützen; Reisende durch die Gegend führen; andere Heartsblood-Leute unterstützen."],
   ["Deadwalker", "Totenriten durchführen und Leichen entsorgen; Vorräte über den Grey einschmuggeln; ungewöhnliche Materialien aus Anderswelten beschaffen; mit den Untoten verhandeln; die Bevölkerung vor Geistern und Phantomen schützen."],
   ["Deep Apiarist", "Bienen halten (gewöhnliche, nicht die magischen) für Honig und Wachs; stabilisierende Schutzzauber gegen das Heart Itself bauen und warten; medizinische Versorgung leisten; durchreisenden Deep Apiarists eine Zuflucht bieten."],
   ["Heretic", "Religiöse Zeremonien leiten, um das Verstreichen der Zeit zu feiern, zu betrauern oder zu markieren; die Kranken heilen und für die Bedürftigen sorgen; das Evangelium des Moon Beneath verbreiten; Verlorenen und Ziellosen geistlichen Trost spenden."],
   ["Hound", "Verteidigungen instand halten; eine Miliz zur Verteidigung der Stadt ausbilden; den Frieden wahren und Streit um Land oder Besitz schlichten; jene aufspüren und bestrafen, die gegen den Haven handeln; durchreisende Hounds im Gegenzug für Dienst unterstützen; Waffen und Munition liefern."],
   ["Incarnadine", "Handelsnetze über Incarnadine-Schreine aufbauen und pflegen; im Auftrag des Herrschers Zehnten von der Bevölkerung eintreiben; den Alltag verwalten und Vorräte überwachen; Streit zwischen verfeindeten Parteien schlichten; jene aufspüren und töten, die eine große karmische Schuld haben."],
   ["Junk Mage", "Als eine Art Stadtzauberer Rat zum Okkulten geben; einen Magieladen betreiben; eine ahnungslose Sekte leiten; etwas Unergründliches mit mystischen Bollwerken gegen das Heart Itself tun."],
   ["Vermissian Knight", "Menschen im Haven und in den Außengebieten schützen; Expeditionen auf Delves zu anderen Landmarken leiten; Maschinen warten; das Vermissian befahren, falls die Siedlung innerhalb seiner Grenzen liegt; große Monster für Ruhm und Profit jagen."],
   ["Witch", "Dem Haven durch ihre edle Abstammung einen Anschein von Legitimität verleihen; mit Wahrsagemagie nützliche Informationen sammeln; medizinische Versorgung durch Operationen oder Tränke bieten; den Hexenkult im Gottesdienst leiten."]
  ], 3)
 ]),
 sec("bedrohungen", "Bedrohungen", 9, [
  p("Das Herz ist ein gefährlicher Ort, und einer der Gründe, einen Haven zu bilden, ist gegenseitiger Schutz. Eine Mauer zu bauen gibt dir theoretisch ein Gebiet, das du kontrollieren und entwickeln kannst, doch die Realität des Lebens in der Stadt unter der Stadt bedeutet, dass das nicht immer stimmt."),
  p("Erschaffe mindestens eine Bedrohung, die über dem Haven schwebt, und stütze dich dabei auf die Domains und das einzigartige Merkmal deines Havens. Hier einige Ideen für Bedrohungen, nach Domain aufgeteilt:"),
  C([
   ["Cursed", "Je tiefer ein Haven liegt, desto wahrscheinlicher ist es, dass sich das Herz erhebt und das Land als sein eigenes zurückfordert; jeder hat schon von einem Haven gehört, der als Ganzes im Boden versank, als die Stadt unter der Stadt ihn verschlang. Engel sind eine seltene Bedrohung (die meisten Menschen hören nie einen Augenzeugenbericht von einem), aber sie stellen eine der schlimmsten Herausforderungen dar, der ein Haven begegnen kann: das Heart Itself, das einen furchtbar zupackenden und unantastbaren Agenten in seinen Dienst entsendet. Der letzte Abschnitt dieses Buchs beschreibt vier spezialisierte Arten von Engeln, die ihr gegen eure Spieler antreten lassen könnt, wenn ihr wollt."],
   ["Desolate", "Pilzfarmen werden unfruchtbar. Für Fleisch gehaltene Tiere wie Schweine, Fresseulen oder Tiefenkrabben fangen Krankheiten und siechen dahin. Viren verbreiten sich ungehindert in und zwischen Dörfern. Ungünstige Pulse verdrehen das Herz zu dürren Ödländern, und da Reisen zwischen Siedlungen Tage dauern kann, kann eine schlechte Ernte einen Haven ruinieren."],
   ["Haven", "Eine der häufigsten Bedrohungen für einen Haven ist nicht das Herz, sondern andere Menschen: rivalisierende Havens oder isolierte Grüppchen verzweifelter Leute versuchen, sich zu holen, was „ihnen“ gehört. Selbst innerhalb einer Siedlung können Streit um fehlende Ressourcen oder ideologische Unterschiede die Leute gegeneinander aufbringen – und wenn man eine Meile unter der Erde nur mit Pilzen und Hoffnung überlebt, können einem die lästigen Angewohnheiten anderer wirklich auf die Nerven gehen."],
   ["Occult", "Havens sind oft auf instabilem metaphysischem Grund gebaut: Abmachungen mit dunklen Wesen, halb verstandene Glyphen auf den Handgelenken der Ältesten und Blutopfer in verborgenen Kammern sind an der Tagesordnung. Manchmal brechen die Schutzzauber wegen mangelnder Wartung oder Expertise zusammen; andernorts wollen rivalisierende Okkultisten Macht, Zugang oder Ressourcen aus einem verwundbaren Haven abziehen und beginnen einen arkanen Krieg."],
   ["Religion", "Trotz der Vorherrschaft der Church of the Moon Beneath im Herzen gibt es Tempel für Hunderte anderer Götter – und mit tief verwurzeltem religiösem Glauben kommt Konflikt. Rivalisierende Sekten, die andere Götter (oder verschiedene Formen desselben Gottes) anbeten, können eine Gemeinschaft zu Gewalt und Ausgrenzung treiben. Mehr als ein Haven ist durch Angriffe im Namen einer Gottheit gefallen."],
   ["Technology", "Die Maschinerie des Herzens ist bestenfalls schlecht verstanden und kann jederzeit ausfallen. Verlässt sich eine Gemeinschaft zum Überleben auf technische Elemente, ist sie auch auf die Großzügigkeit derer angewiesen, die die Fähigkeiten zur Reparatur haben, und auf die Verfügbarkeit passender Materialien. Retroengineers verlangen einen hohen Preis für ihr Fachwissen, und Ersatz für kaputte Teile muss aufgespürt oder mühsam angefertigt werden. Wer wertvolle oder faszinierende Geräte besitzt, findet sein Zuhause womöglich belagert von anderen, die sie haben wollen."],
   ["Warren", "Das Herz ist von Gängen und Nebenwegen durchlöchert; manche natürlich, manche von Menschen gemacht. Einen Haven zu verteidigen kann wegen der verschlungenen, sich überlagernden Korridore um ihn herum nahezu unmöglich sein. Zudem könnten die Bewohner ihre Häuser unter dem eigenen Gewicht einstürzen sehen, wenn der Bau im Haven besonders aggressiv betrieben wird."],
   ["Wild", "Bestien, Monster und besonders aggressives Gelände sind ein häufiges Problem. Die Kreaturen des Herzens reichen von beunruhigend bis tödlich, und sie haben keinen Respekt vor Stadtgrenzen. Wenn sich Havens in ihre Jagd-, Brut- oder Aufzuchtgebiete ausdehnen, wagen sie sich hinein, um Nahrung, Wasser und Obdach zu finden (nicht dass alle Heartsblood-Bestien Nahrung, Wasser oder Obdach im menschlichen Sinn bräuchten). Mit wilden Bedrohungen kann man nicht verhandeln, aber sie sind weniger gerissen und einfallsreich als Menschen."]
  ], 3)
 ]),
 sec("bedrohungen2", "Beispiele: High Rise, Cluster", 9, [
  G(2, [[
   note("High Rise", [
    "Von Legionen spektraler Untoter geplagt, haben die Bewohner von High Rise beschlossen, das Problem mit Opfern zu bekämpfen – Geister mit Geistern zu bekämpfen, sozusagen.",
    "Die Siedlung thront auf mehreren zwanzigstöckigen Gebäuden, die durch wacklige Brücken verbunden sind; vom siebzehnten Stockwerk abwärts sind die Phantome zu zahlreich und zu hungrig, um Besiedlung zuzulassen. Etwas hält sie davon ab, in die oberen Ebenen aufzusteigen.",
    "Die Priester von High Rise (die sich Swanfall-Kult nennen, obwohl ich bezweifle, dass einer von ihnen je einen Schwan gesehen hat) glauben, dass häufige Opfer ihrer besten und klügsten Jugendlichen der Schlüssel zum Schutz ihrer Heime sind. Etwa einmal im Monat stürzen sich ein paar Leute kopfüber von den Dächern und zerschellen unten zu Brei. Das ist eine große Ehre, und sie scheinen glücklich genug darüber zu sein, daher scheue ich mich, sie zu kritisieren. Viele Narren haben im Streben nach Ruhm weit Schlimmeres getan."
   ])
  ], [
   note("Cluster", [
    "Ich schrieb weiter vorn in diesem Band ausführlich über meine Faszination für Raubtiergebäude – jene Bauten aus Holz, Metall und Stein, die sehr lebendig und hungrig sind. Sie tarnen sich als normale Gebäude, um Beute anzulocken.",
    "In Cluster hat ein Heartsblood-Mann namens Sekh Drumford (wie jene verräterischen Hexen von Hallow) gelernt, sie zu kontrollieren. Anders als bei den Hexen ist Drumfords Beziehung zu den Gebäuden jedoch nicht die von Herr und Diener, sondern von Raubtier und Beute.",
    "Cluster ist eine Falle für Fallen. Er besteht ganz aus Raubtiergebäuden, die dorthin gelockt und dann aggressiv umgebaut wurden – oder getötet, mit anderen Worten. In letzter Zeit, da die Siedlung gewachsen ist, hat Drumford begonnen, die Bauten zu züchten. Statt jeden Neuankömmling sofort zu töten, versucht er, ihr Wachstum und ihre Bewegungen zu etwas Nützlicherem zu verbiegen.",
    "Mir wurde gesagt, dass es derzeit elf Kneipen, zwei Schneiderwerkstätten, eine Parfümerie-Boutique und einen kleinen überdachten Markt gibt, alle grob zur Form eines Dorfes zusammengenäht. Drumford versucht gerade, ein Theater zu züchten, und braucht Fleisch, um es zu füttern."
   ])
  ]])
 ]),
 sec("regeln", "Regeln, Name, Fragen", 11, [
  p("Ein Haven wird größtenteils durch fiktives Material statt durch Spielmechanik dargestellt, aber vor Abschluss der Erschaffung gibt es einige Überlegungen."),
  C([
   ["Default Stress", "Der **Default Stress** ist ein grober Hinweis auf die Gefahrenstufe für Spielerfiguren, die sich im Haven aufhalten. Je kleiner die Würfelgröße, desto sicherer die Lage; ein Haven mit Default Stress W4 fühlt sich ganz anders an als einer mit W8. Ein hoher Stress-Würfel ist aber nicht zwingend ein Zeichen von Chaos oder Unordnung: Ein streng geführtes Hounds-Lager könnte Default Stress W10 haben, da jedes Fehlverhalten sofort mit gewaltsamer Vergeltung beantwortet werden könnte."],
   ["Haunts", "**Haunts** bieten den Spielerfiguren die Möglichkeit, Ressourcen gegen Heilung und Nachschub einzutauschen. Jeder hat eine Nichtspielerfigur oder zumindest ein interessantes Konzept, mit dem die Delver interagieren, wenn sie Stress entfernen.", "Überlege genau, welche Resistenzen dein Haven bezogen auf die Klassen deiner Spielerfiguren abdecken kann; können sie zu Hause keine Heilung erhalten, müssen sie anderswohin reisen. Zwei oder drei Haunts geben dir die Gelegenheit, den Haven mit Figuren und Diensten auszuarbeiten, aber halte die Würfelgröße um W6, um die Spieler zum Verbessern anzuregen (siehe *Heart* S. 131 für die vollständigen Regeln zum Aufwerten von Haunts). Hast du nur einen Haunt, ist es oft interessant, ihm eine hohe Würfelgröße zu geben, als Zeichen für etwas wirklich Besonderes, das es zu verteidigen lohnt."],
   ["Resources", "**Ressourcen** sind wertvolle Gegenstände, die im oder nahe beim Haven zu finden sind. In Havens gehören viele Ressourcen den Bewohnern, die Spielerfiguren müssen also etwas im Gegenzug bieten oder sie stehlen. Je höherwertiger und vielfältiger die Ressourcen in einem Haven, desto wohlhabender ist er."]
  ], 3),
  G(2, [[
   h("Name"),
   p("Dinge zu benennen ist schwer. Wir empfehlen, es einfach zu halten und bei einem Thema zu bleiben. Hier einige Ideen:"),
   ul(["Wähle eine Fremdsprache, übersetze ein paar wichtige Wörter und vertausche einige Buchstaben. Mische sie, bis nur noch Klang und Gefühl der Wendung übrig sind.","Kombiniere zwei Substantive, deren Klang dir gefällt.","Stiehl die Namen ländlicher Dörfer von der anderen Seite deines Landes.","Benenne ihn nach dem Gründer, einer legendären Heldin oder einer schicksalhaften Schlacht."])
  ], [
   h("Unbeantwortete Fragen"),
   p("Der letzte Teil der Haven-Erschaffung ist, herauszufinden, welche Fragen ihr im Spiel beantworten wollt. Jedes letzte Detail der Siedlung vor Kampagnenbeginn auszuarbeiten macht ihre Erkundung trocken und langweilig; je mehr Details ihr offen lasst, desto flüssiger läuft das Spiel. Ihr könnt ja jederzeit im Spiel Dinge festlegen."),
   h("Weitere Haven-Fragen"),
   ul(["Warum kommen Leute hierher?","Warum gehen Leute fort?","Was ist das Beste an diesem Haven?","Welche Geschichten erzählen die Leute hier ihren Kindern?","Welche Tiere und welches Ungeziefer gibt es hier?","Was ist das Geheimnis, das sie Außenstehenden nie zu verraten versprechen?"])
  ]])
 ]),
 sec("wyrmpit", "Beispiel-Haven: Wyrmpit", 12, [
  p("Wir (Chris und Grant) besprechen die Domains eine Weile und entscheiden uns für **Desolate** – wir finden es interessant, etwas zu bauen, das sich hauptsächlich auf das Land konzentriert, nicht auf die Leute. Das kann sich aber noch ändern! Wir beschließen, dass der Haven in einem Pass in einer großen Schlucht liegt, die einen der wenigen Zugangswege in diesem Teil des Herzens bildet, und dass das Land ringsum von Generationen von Schlachten vernarbt und tot ist. Chris schlägt vor, dass der Ort auf einem alten, bröckelnden Tempel gebaut ist; Grant stimmt zu und meint, dass dort unten etwas Großes und Gefährliches schlummert.", true),
  G(2, [[
   h("Tiefe"),
   p("Der Haven bildet einen Durchgang zwischen den Tiefen 1 und 2."),
   h("Etwas Einzigartiges"),
   p("Was schlummert da unten? Wir reden eine Weile über Wächter der Unterwelt und verwerfen die Idee eines dreiköpfigen Hundes (zu abgenutzt), bevor wir bei der Lösung landen: ein riesiger Wyrm! Wir können uns nicht ganz entscheiden, ob er ringelwurm- oder reptilienartig ist, aber er ist definitiv riesig und windet sich um eine Grube und frisst sich dabei in einem endlosen Ouroboros selbst. Die Leute hier halten ihn für sehr weise; sie lauschen seinem zischelnden Winden und versuchen, Bedeutung daraus abzulesen. Und falls der Haven je ernsthaft bedroht wird, glauben sie, dass der Wyrm sich erheben wird, um sie zu verteidigen."),
   p("Der uralte Tempel ist in einem Tunnel mit gläsernem Boden gebaut, und jeder, der hindurchgeht, kann das gewaltige Geschöpf unter seinen Füßen in sich selbst gekringelt sehen. Die Bewohner, die Marktstände mit Andenken und weichen Drogen betreiben, verlieren an den meisten Tagen nicht einmal ein Wort darüber."),
   h("Kunst"),
   p("Die Leute malen und schnitzen hier Wyrms auf alles. Die Miliz bekommt ein sich windendes Schlangentattoo als Zeichen der Zugehörigkeit, das mit jedem Dienstjahr länger wird. In den Häusern, die zu beiden Seiten des Tors in die Höhlenwände gebaut sind, bemalen die Bewohner ihre weißgetünchten Wände mit Wyrms in den extravagantesten Farben, die sie sich leisten können.")
  ], [
   h("Gesichter"),
   ul(["Felicity die Verwalterin ist die Anführerin des Hexenzirkels, der den Ort leitet, und handelt nach der göttlichen Weisheit des sich windenden Wyrms. Seltsamerweise scheint diese Weisheit stets ihr und ihrem Orden zu nützen. Sie und die anderen Hexen sind üppig gekleidet und behängt mit Schmuck und haben gut eingerichtete Wohnungen im Bereich über dem Tempel. (Wir schwankten, ob die Person, die als Orakel fungiert, die Verwalterin oder die Rebellin sein soll, aber das hier schien interessanter; und wir sind uns nicht ganz sicher, ob sie wirklich etwas deutet oder sich einfach etwas ausdenkt.)","Lech der Rebell ist einer von einer Handvoll Hounds, die hier arbeiten, die Verteidigung der Stadt überwachen und Milizgruppen ausbilden. Lech wurde hierher abkommandiert, nachdem er seinen Vorgesetzten verärgert hatte, und ist überzeugt, dass der Wyrm die Bevölkerung nicht retten wird; er glaubt, dass er in einem Jahr oder weniger erwachen und den Ort verwüsten wird. Er hat die Berechnungen dazu, die er dir zeigen kann.","Vostair die Stimme ist ein Markthändler und gelegentlicher Milizionär. Er mag starken Trunk und starke Liebhaber, ist stolz auf sein üppig geöltes Körperhaar und hat die Ehre, einer der am wenigsten betrügerischen Händler auf dem Tempelboden zu sein."]),
   h("Rollen der Spielerfiguren"),
   p("Wir haben keine festen Spielerfiguren, da dies ein Beispiel ist, aber wir haben für die Übung einige erfunden. Es sind:"),
   ul(["Ein Vermissian Knight, der wertvolle Fracht durch das Gebiet des Havens eskortiert und die Grenzen patrouilliert.","Ein Hound, der mit Lech beim Ausbilden der Miliz zusammenarbeitet.","Eine Witch, die Felicitys Zirkel als besserer Dienstmädchen zugeteilt wurde.","Ein Junk Mage, der mit seinem rotznäsigen Cousin im Tempelmarkt einen Stand mit okkultem Krimskrams betreibt."])
  ]])
 ]),
 sec("wyrmpit2", "Wyrmpit: Bedrohung, Regeln, Name", 13, [
  G(2, [[
   h("Bedrohungen"),
   p("Wir wollen das mit dem Rest des Buchs verknüpfen und beschließen, auf die Domain **Cursed** zurückzugreifen und einen Engel gegen den Haven antreten zu lassen. Er nähert sich, stoisch von Tiefe 3 hinauf zum Tor marschierend. Was will er? Das ist nicht ganz klar. Vielleicht interessiert er sich gar nicht für Wyrmpit selbst und will es nur nutzen, um zur Oberwelt zu gelangen.", true),
   p("Das erste Spiel beginnt mit der Ankunft eines wahnsinnig blickenden Reisenden, der auf dem Tempelmarkt herumtorkelt und darum bettelt, dass ihn jemand zur Oberwelt eskortiert, bevor der Engel eintrifft."),
   h("Regeln"),
   p("Der Default Stress des Havens ist W4 auf der Seite der Tiefe 1 und W6 ab dem Tempel auf der Seite der Tiefe 2. Wir erfinden zwei Haunts – Temple Market (Supplies W8) und Sascha, eine Hexe, die sich an medizinischen Experimenten versucht (Blood W6). Schließlich sind die verfügbaren Ressourcen Höhlenpilze aus kleinen Farmen (W6, Wild) und eine Vielfalt von Souvenirs und kitschigen Kunstwerken (W6, Haven). Beschließt ihr, in die Wohnungen der Hexen einzubrechen, sind deren Kostbarkeiten (W8, Haven) und ihre Bücher der Blutzauberei (W10, Occult, Beacon).")
  ], [
   h("Name"),
   p("Nach langer Diskussion beschließen wir, zwei altmodische Substantive („Worm“ und „Pit“, wegen des großen Wurms in der Grube im Zentrum der Stadt) zu einem Namen zu kombinieren. Dann änderten wir „Worm“ in „Wyrm“, weil es für die Seltsamkeit und das Geheimnisvolle des Ortes passender klang. Es klingt ein bisschen wie „armpit“ (Achselhöhle), aber nicht genug, um uns zu einer Änderung zu bewegen."),
   h("Unbeantwortete Fragen"),
   p("Was will der Engel? Spendet der Wyrm tatsächlich Weisheit, oder denken sich die Hexen alles aus? Wann wird der Wyrm erwachen, und was wird noch stehen, wenn es soweit ist?"),
   p("Und worum geht es eigentlich bei diesen seltsamen Zeichen an den Tempelwänden?")
  ]])
 ])
]};

var spiel = {id:"zuflucht-spiel", t:"Haven-Spielleitung", p:13, secs:[
 sec("rhythmus", "Rhythmus und Nachbarn", 14, [
  G(2, [[
   h("Rhythmus"),
   p("Der typische Rhythmus eines Haven-Spiels verläuft grob so:"),
   ul(["Der Haven ist bedroht.","Die Spielerfiguren brechen zu einem Delve auf, um etwas zu finden, das hilft.","Sie überwinden Hindernisse, wenn sie die Landmarke erreichen, und bekommen, was sie brauchen.","Sie kehren in den Haven zurück und sehen, wie er sich in ihrer Abwesenheit entwickelt oder verändert hat.","Wiederholen, bis die Bedrohung besiegt ist oder der Haven fällt."]),
   p("Du musst das natürlich nicht genau so befolgen – es ist nur die zentrale Schleife des Spiels. Die Details liegen bei dir und deinen Spielern, ganz nach dem, was sich in dem Moment richtig anfühlt, und nach den grausamen Launen des Fallouts."),
   h("Nachbarn"),
   p("Du hast einen Haven als Mittelpunkt deines Spiels erschaffen; nun ist es Zeit, die Stadt unter der Stadt darum herum zu skizzieren. Wähle oder erschaffe drei oder vier Landmarken und platziere sie neben dem zentralen Haven. Eine davon hat eine Verbindung, halbiere also die Resistance des Delves. Die anderen funktionieren als Standard-Delves."),
   p("Jede der Landmarken hat etwas, das der Haven braucht (oder das den Bewohnern zumindest nützen würde), und ein Problem, das gelöst werden muss, bevor die Spielerfiguren Zugang bekommen. Sieh dir deinen Haven an, besonders die Bedrohungen, und überlege, was ihm helfen würde, die vor ihm liegenden Herausforderungen abzuwehren oder zu überwinden. Mit Wyrmpit als Beispiel hier drei Landmarken, aufgeschlüsselt nach dem, was sie bieten können und was den Delvern im Weg steht:")
  ], [
   C([
    ["Chollerous", "Ein Ableger der Church of the Moon Beneath, gegründet von einer gewalttätigen Splittersekte, liegt auf der Tiefe-1-Seite von Wyrmpit. Sie haben ein starkes Hounds-Kontingent, daher könnte ihre Unterstützung bei der Verteidigung des Havens von unschätzbarem Wert sein. Das Problem: Jemand hat den unsterblichen Märtyrer gestohlen, den sie unter ihrem Heiligtum eingesperrt hielten, und der Tempel beginnt zu zerfallen. Sie glauben, es war ein Innentäter, und brauchen Antworten."],
    ["Hallow", "Die spirituelle und politische Heimat der Hexen liegt jenseits der Tiefe-2-Seite von Wyrmpit. Die Delver können ihre Macht nutzen, um den Haven gegen das Vermissian zu verteidigen, oder sie auf ihre Seite ziehen, wenn sie Felicity und ihren Zirkel absetzen wollen. Die Hexen brauchen einen Gefallen: Eine der Spioninnen, die sie in Felicitys Dienst platziert haben, ist abtrünnig geworden, und sie wollen, dass ihr sie aufspürt und zur Befragung bringt. Sie wissen allerdings nicht, welche es ist. Der regelmäßige Verkehr zwischen Hallow und Wyrmpit bedeutet, dass zwischen beiden Landmarken eine Verbindung besteht."],
    ["The Red Market", "Ein großer, sich verschiebender, kriegszerrissener Souk, einer hungrigen Schuldengottheit gewidmet, ist über uralte Kanäle und Kriechgänge auf der Tiefe-2-Seite von Wyrmpit erreichbar. Einer der Incarnadine-Lords dort bietet den Delvern die Chance, ihre wertvollen und verborgenen Handelsnetze zu nutzen, im Austausch dafür, dass sie helfen, im Markt neues Gebiet herauszuschlagen."]
   ]),
   note("Marsh-Hallow", [
    "Hier wurden die Gebeine von Heiligen und Märtyrern übereinandergehäuft, bis die Haufen einstürzten. Gruft auf zerfallener Gruft wurde errichtet; Mausoleum auf bröckelndem Mausoleum; Grabsteine wurden gestapelt, um Sarkophage zu bauen, bis die Fundamente dieses Ortes ein wild zusammengewürfeltes Reliquiar bildeten. Die Geister der Gläubigen kratzen und stöhnen unter jeder Diele und Platte.",
    "Die Leute hier haben tausend kleine Rituale, die sie jeden Tag durchlaufen, um diese Phantom-Heiligen zu besänftigen, doch es ist kein einseitiger Handel. Gelegentlich – besonders wenn die Siedlung bedroht ist – formen die Geister ein Mischwesen aus Knochen und Mauerwerk, um das Dorf zu verteidigen, das leicht doppelt so hoch und breit wird wie ein Mann.",
    "Mir wurde auch gesagt, dass die Geister das manchmal tun, wenn die Siedlung nicht bedroht ist, was deutlich weniger nützlich ist."
   ])
  ]])
 ]),
 sec("fallout", "Fallout: Leicht", 15, [
  p("Ein Haven sammelt keinen Stress an und hat keinen Resistance-Wert. Das tun nur die Menschen darin (und die Spielerfiguren, die ihn unterstützen) – und letztlich ist der Haven für seine Existenz auf seine Bewohner angewiesen. In einer Haven-Kampagne kannst du Unglück für die Siedlung durch **Fortune**- oder **Supplies**-Fallout abbilden, der bei den Spielerfiguren markiert wird."),
  p("Du wirst wahrscheinlich feststellen, dass Spieler gern Verbindungen zwischen nahen Landmarken herstellen – es wird angenommen, dass sie jeden Delve mindestens zweimal unternehmen müssen. Du wirst auch feststellen, dass es sie wirklich trifft, wenn du ihnen diese Verbindungen durch schweren **Fortune**- oder **Echo**-Fallout wegnimmst; tu das also mindestens einmal – zeige ihnen, dass das Herz nicht stabil ist und dass jeder Versuch, außerhalb einer Landmarke etwas Dauerhaftes zu bauen, vergeblich ist."),
  p("Da sich die Geschichte des Spiels um eine einzelne Bedrohung dreht (oder mehrere, wenn die Spieler besonders unglücklich sind), kannst du Fallout gut nutzen, um darzustellen, wie es für den Haven gefährlicher wird. Wir haben unten einige Beispiele genannt, aber es sei hier wiederholt: Fallout wird zu einer tickenden Uhr, die von leicht (Gerüchte über einen Feind, der Macht sammelt) über schwer (Streiks oder Überfälle gegen deinen Haven) bis kritisch (der Haven wird zerstört, oder seine Existenz hängt am seidenen Faden) reicht."),
  p("Unten stehen einige Beispiel-Fallouts, aus denen du wählen kannst."),
  h("Leicht"),
  C([
   F("Approach", "Fortune", "Wer oder was auch immer den Haven bedroht, kommt der Erfüllung seiner Ziele einen Schritt näher – vielleicht erwirbt er wertvolle Ressourcen, beansprucht Territorium oder nähert sich einfach unaufhaltsam den Siedlungstoren. Die Spielerfiguren sehen Beweise dafür oder hören davon, bevor die Sitzung vorbei ist.", S),
   F("In Danger", "Fortune", "Jemand, der dir wichtig ist, steckt in Schwierigkeiten, und es ist deine Schuld; oder es ist zumindest deine Aufgabe, ihn zu retten.", S),
   F("Infiltrated", "Fortune", "Feindliche Agenten haben es geschafft, sich in die Grenzen einzuschleichen. Sie handeln als Spione und Saboteure, und die Spielerfiguren müssen hart arbeiten, um die Bedrohung aufzuspüren.", A),
   F("Lack", "Supplies", "Die Spielerfigur hat zu gierig von den Vorräten genommen, die den Haven tragen (Essen, Medizin, Wasser, Brennstoff), und nun müssen Leute darben. Wenn sie das nächste Mal in der Landmarke ankommt, wird sie mit den Folgen ihres Handelns konfrontiert.", S)
  ], "4s")
 ]),
 sec("fallout-schwer", "Fallout: Schwer, kritisch", 16, [
  h("Schwer"),
  C([
   F("At the Gates", "Fortune", "Die Gegner des Havens gehen gegen die Siedlung vor. Meist ist es ein Überfall auf Vorräte, es kann aber auch eine Blockade oder ein Versuch sein, Gebäude oder Ressourcen zu zerstören.", S),
   F("Cut Off", "Fortune/Supplies", "Ein Zugangsweg in den Haven wurde durch Umweltveränderung, Pech oder Feindeinwirkung abgeschnitten. Bis die Figuren die Verbindung wiederherstellen, zählen ihre ausgegebenen Ressourcen eine Würfelgröße niedriger, wenn sie Haunts im Haven nutzen.", A),
   F("Dead", "Fortune", "Jemand, der dir wichtig ist, ist tot, und es ist deine Schuld, oder du redest dir ein, dass es deine Schuld ist. Oder: Alle anderen denken, es ist deine Schuld, egal, was wirklich geschah. Ist er eine Bindung, verlierst du sie; leitet er einen Haunt, entferne ihn entweder aus dem Haven oder halbiere seine Würfelgröße, da unerfahrene Lehrlinge übernehmen.", S),
   F("Information Leak", "Fortune", "Spione im Haven berichten über deine Bewegungen, und wenn du versuchst, etwas Schwieriges durchzuziehen (eine seltene Ressource sichern, eine Handelsroute einrichten, Angreifer abwehren), merkst du, dass dein Plan durch ihr Handeln unterlaufen wurde. Deine nächste Handlung nach der Entdeckung des Täuschungsmanövers ist **Gefährlich**; danach, vorausgesetzt du überlebst, musst du dir einen neuen Plan ausdenken.", S),
   F("Sabotage", "Fortune", "Ein lebenswichtiges Element (wahrscheinlich ein Haunt, eine Verteidigungsanlage oder ein Gerät, auf das sich der Haven verlässt) wurde sabotiert – vielleicht irreparabel.", S),
   F("Seeking Shelter", "Fortune", "Ein Zustrom von Flüchtlingen aus einem zerstörten nahen Haven bringt die Siedlung an ihre Grenzen. Gemüter erhitzen sich, und Diebstahlsvorwürfe fliegen. Können die Spielerfiguren verhindern, dass sich die Lage zu Lynchjustiz entwickelt, oder zumindest die Schuld einem entbehrlichen Sündenbock zuschieben?", S)
  ], 3),
  h("Kritisch"),
  C([
   F("Fallen", "Fortune", "Der Haven ist so beschädigt und die Leute so entmutigt (oder tot), dass er nicht mehr als Siedlung funktionieren kann. Er wird aufgegeben, und obwohl er in Zukunft wiederaufgebaut werden könnte, ist es für den Moment ein viel größeres Anliegen, die Flüchtlinge zu schützen und Sicherheit zu finden.", S),
   F("Hunger", "Fortune", "Dem Haven ist das Essen ausgegangen; Leute ziehen fort, und die, die bleiben, streiten um die wenigen verbliebenen Reste. Du kannst keine Haunts nutzen, und Bindungen fehlen entweder oder funktionieren nur halb so gut (du markierst zwei Stress für jeden Punkt Stress, der bei deiner Figur entfernt wird). Wenn du nicht bald etwas unternimmst, stellt der Haven seinen Betrieb ein.", A),
   F("Killer", "Fortune", "Vielleicht war es ein verirrter Schuss oder ein tragischer magischer Rückschlag – oder vielleicht wolltest du es tun und hast ihm mit bloßen Händen das Leben ausgewürgt. Jedenfalls: Jemand, der dir wichtig ist, ist tot, und du warst es. Nun musst du der Entdeckung entgehen, die Leiche verstecken und dir ein Alibi ausdenken, damit du beim nächsten Glockenschlag nicht auf dem Stadtplatz gehängt wirst.", S)
  ], 3),
  note("Our Lady of Perambulation Church", [
   "Wenn ein nomadisches Leben für dich heilig ist, wo versammelst du dich zum Gottesdienst? Offenbar nimmst du deine Kirche und trägst sie herum.",
   "Die Anhänger von Our Lady Of Perambulation zählen Hunderte, und sie sind stets auf einer endlosen Pilgerreise ins Nirgendwo. Den Ergebensten ist es erlaubt, ihre Hochkirche zu tragen, ein eckiges Gebäude aus Holz und Knochen. Sie bewegen sie auf einer Route durch die Unterstadt, die von einem wahnsinnigen Orakel bestimmt wird, das, in narkotischen Rauch gehüllt, in der Zentralkammer der Kirche sitzt.",
   "Die Gläubigen bieten Unterkunft in den Hinterzimmern dieser Kirche. Sie ist billig, und die Gläubigen sind freundlich genug, aber der beißende Rauch kriecht überallhin, und ihr ewiges Trällern von Hymnen (das, wie mir gesagt wurde, seit zwölf Jahren ununterbrochen gesungen wird) kann einem die Zähne klappern lassen."
  ])
 ]),
 sec("beats", "Haven-Beats", 17, [
  G(2, [[
   p("Du möchtest den Spielern vielleicht Haven-spezifische Beats zusätzlich zu den Beats ihrer Berufung anbieten. Anders als Berufungs-Beats geben diese beim Erreichen keinen Zugang zu Fortschritten – stattdessen geben sie Zugang zu einer neuen Bindung oder entfernen Stress von einer bestehenden Bindung."),
   p("Erstelle drei oder vier Haven-Beats, wenn du die Siedlung erschaffst, halte sie für alle Spieler sichtbar (entweder in der Mitte des Tisches oder in einem gemeinsamen Dokument/einer Webseite) und lass sie frei wählen und kombinieren. Du kannst Haven-Beats im Spiel aktualisieren, um den sich ändernden Zustand des Havens abzubilden."),
   p("Das ist eine großartige Möglichkeit, deine Spieler zu lenken und sie mechanisch dafür zu belohnen, dass sie sich mit dem Haven beschäftigen; und wenn sie regelmäßig heimkommen und Stress auf ihre Bindungen abladen, werden sie diese auch brauchen."),
   p("Mehr zu Bindungen und wie sie Stress erhalten, siehe *Heart* S. 98."),
   h("Ideen für Haven-Beats"),
   ul(["Angreifer abwehren, die wertvolle Ressourcen aus dem Haven stehlen wollen","Den Sorgen des Rebellen zuhören und ihm deine Unterstützung anbieten","Die Verteidigung des Havens ausbauen","Einen Mörder aufspüren, der sich im Haven versteckt","Im Auftrag des Verwalters gegen den Rebellen vorgehen","Die Stimme retten, wenn sie in Schwierigkeiten ist","Neue Bewohner in den Haven bringen","Den Tempel in der Stadtmitte wiederaufbauen","Die Überlebenden eines Angriffs evakuieren","Materialien beschaffen, um die Schutzzauber der Stadt gegen das Herz zu verstärken","Einen Geist zur Ruhe betten","Vorräte für die Stadtmiliz von zwielichtigen Söldnern stehlen","Die Seele des alten Bauern Asharam erlösen","Mit jemandem ein schönes Date haben","Gemeinschaftskunst schaffen, die zum Erscheinungsbild des Havens beiträgt"])
  ], [
   note("Typhon", [
    "Legenden berichten von einem Portal in eine dunkle und grausame Dimension unter dem Gasthaus im Zentrum von Typhon. Es ist ein Ort windenden Grauens und unendlicher Monster, an dem die größten Krieger sowohl die Kraft ihres Arms als auch die Stärke ihres Geistes prüfen. Es heißt, von hier krabbeln die Pitchkin; hier lebt der Große Minotaurus; hier halten die ruhelosen Wächter der Toten, juwelenbesetzt und in Gold gekleidet, Wache über die schlummernden Körper unsterblicher Gottheiten. Der Wirt flüstert, dass Schätze jenseits des Verstehens von Mensch, Elf oder Gnoll jene erwarten, die mutig genug sind, sich in das teerschwarze Labyrinth zu wagen.",
    "Es ist alles Blödsinn. Das Gasthaus in Typhon ist nur das: ein Gasthaus, vielleicht mit einem etwas größeren Keller als gewöhnlich. Der Besitzer ist ein Lügner, der gern tollkühne Abenteurertypen sturzbetrunken macht und sie nach unten schickt, damit sie von sechs seiner entfernten Cousins ausgeraubt werden. Außerdem sind die Zimmer überteuert und das Bier ist wässrig."
   ])
  ]])
 ])
,
 sec("gris", "Gris Hannemans Hinterlassenschaften", 24, [
  p("Es folgt eine Liste der Ausrüstung, die Gris Hanneman benutzte (oder die er laut seinem Buch benutzte). Wo es passt, sind Werte für die erfundene und die tatsächliche Fassung angegeben – zuerst das Artefakt aus dem Buch, dann der weniger beeindruckende echte Gegenstand."),
  {t:"karten", n:3, x:[
   {t:"Die Pistole der Familie Hanneman", b:[p("**Kill W8, Ranged, Reload, Good-Quality**"), p("*Echt:* Die Pistole, die Gris in Redcap Grove aus den Händen einer Leiche zog – **Kill W8, Ranged, One-shot.** Verleiht **Knack: Raub**.")]},
   {t:"Engelskugeln", b:[p("**Wie Waffe, Limited 6.** Fügt der Benutzer einem Engel Stress zu, wird der **Protection**-Wert des Engels nicht vom Stress abgezogen.")]},
   {t:"Geistschärfende Pillen", b:[p("In Hannemans Unterkunft gefunden. **Limited 6.** Verursacht bei Einnahme W6 Stress auf **Mind**, verleiht aber bis zum Ende der Sitzung **Knack: Engel aufspüren**.")]},
   {t:"Die Findeknochen", b:[p("**Delve W8, Wyrd, Excellent Quality**"), p("*Echt:* Ein Gewirr aus blutbefleckten Vogelknochen und Schnur – **Delve W4.** Verleiht **Knack: Einbruch**.")]},
   {t:"Die Mutter des Fleisches", b:[p("**Mend Blood W8, Potent, Wyrd.** Einmal pro Sitzung einsetzbar, um ein leichtes oder schweres **Blood**-Fallout zu entfernen; die geheilte Person markiert W6 Stress auf **Echo**.")]},
   {t:"Gris Hannemans Finger", b:[p("Auffällig abwesend von seiner Hand, als man ihn zuletzt sah. **Delve W6.** Drei Finger, die in die Richtung des nächsten Engels, Havens und Rauschmittels in der Umgebung zeigen.")]},
   {t:"Der stolze Bociferous, Canid Corvidae", b:[p("**Delve W8, Good Quality**"), p("*Echt:* Der elende Bociferous, ein räudiger Halbhund, der glaubt, er sei eine Krähe – **Delve W6, Expensive** (insofern, als er deine Vorräte frisst, wenn du nicht hinsiehst).")]}
  ]},
  G(3, [[
   note("Gris’ Notiz", ["Meine vorrangige Aufgabe ist es, Engel zu dokumentieren, nicht sie zu jagen, doch ich bin mir der Notwendigkeit eines Mindestmaßes an Selbstverteidigung durchaus bewusst. Zu diesem Zweck habe ich eine Pistole feiner Machart mitgebracht: ein Geschenk meines Vaters, selbst ein Entdecker, der sie mir auf dem Sterbebett überließ, als er erkannte, dass es Zeit war, die Fackel weiterzureichen. Von den Büchsenmachern des Hauses Gryndel gefertigt, hat diese Pistole einen gewaltigen Bums (mit entsprechendem Rückstoß) und hat mich nie im Stich gelassen – bis sie mir während meiner Zeit im Leichengott von einem langfingrigen Lumpen gestohlen wurde.", "Während meiner Zeit im Heart entwickelte ich ein Gebräu, mit dem ich meine Munition behandelte, damit die Kugeln Engel besser von weiteren Angriffen abhielten. Es bestand hauptsächlich aus Material, das von den Kreaturen selbst gewonnen wurde (oder aus der kosmischen Losung, die sie hinterlassen), zu Pulver zerrieben. Dieses wird beim Kugelgießen dem Blei beigemischt."])
  ], [
   note("Gris’ Notiz", ["Eine abtrünnige Bluthexe, die den hinterhältigen Zauberern von Hallow den Rücken gekehrt hatte, lehrte mich während unserer kurzen (aber ereignisreichen) Affäre das Geheimnis, Seherknochen herzustellen. Mein eigener Satz Knochen enthielt okkulte Erkenntnisse außerhalb ihres Verständnisses; ich glaube, das brachte sie gegen mich auf und führte zu ihrem Fortgang.", "Nach einer Auseinandersetzung mit ein paar Taugenichtsen verlor ich drei Finger meiner linken Hand. Zum Glück nahm mich eine Heartsblood-Enklave auf und zeigte mir ihre seltsamen Heilkünste. Am seltsamsten war die Mutter des Fleisches: ein Glas zappelnden, halblebendigen Hackfleischs, das mit Pflanzenmaterial vermischt und als eine Art Umschlag auf Wunden gelegt wird. Meine Finger wuchsen viel kräftiger nach als zuvor, auch wenn ich den Anblick ihrer Fingerabdrücke nicht mehr ertrug."])
  ], [
   note("Gris’ Notiz", ["In High Rise lernte ich meinen Gefährten Bociferous kennen – einen Hund irgendeiner Art oder vielleicht einen entfernten Verwandten eines solchen. Bociferous hatte die Merkmale der Albinokrähen angenommen, die dort auf jedem Geländer und jedem Fensterbrett sitzen: gelbweiße Federn, rosige Augen und einen Schnabel. Trotz seiner Vogelmutationen behielt er die allgemeine Gestalt und das unterwürfige Wesen eines Hundes, und seine Federn erlaubten ihm zu gleiten (wenn auch nicht wirklich zu fliegen). Ich vergötterte Bociferous, und mit echter, aufrichtiger Trauer aß ich ihn, als unserer Gruppe Essen und entbehrliche Teammitglieder ausgingen."])
  ]])
 ])
]};
var S = window.HT_NACH.spielleitung = window.HT_NACH.spielleitung || {t:"Spielleitung", p:104, subs:[]};
S.subs.push(haven, spiel);
})();
